using System;using Mono.Cecil;using Mono.Cecil.Cil;
class GuiCaptionContracts {
 static void Need(bool value,string reason){if(!value)throw new Exception(reason);}
 static void Main(){var a=AssemblyDefinition.CreateAssembly(new AssemblyNameDefinition("Fixture",new Version(1,0)),"Fixture",ModuleKind.Dll);var module=a.MainModule;
  var gui=new TypeReference("UnityEngine","GUILayout",module,module.TypeSystem.CoreLibrary);var label=new MethodReference("Label",module.TypeSystem.Void,gui);label.Parameters.Add(new ParameterDefinition(module.TypeSystem.String));
  var type=new TypeDefinition("","Fixture",TypeAttributes.Public,module.TypeSystem.Object);module.Types.Add(type);
  Func<MethodDefinition> method=()=>{var m=new MethodDefinition("Display",MethodAttributes.Static|MethodAttributes.Public,module.TypeSystem.Void);type.Methods.Add(m);return m;};
  var direct=method();var il=direct.Body.GetILProcessor();var text=il.Create(OpCodes.Ldstr,"Unit");il.Append(text);il.Append(il.Create(OpCodes.Call,label));il.Append(il.Create(OpCodes.Ret));Need(GuiCaptionAudit.Require(direct,text)==label.FullName,"Unit caption succeeds without changing internal unit key");
  var stored=method();stored.Body.Variables.Add(new VariableDefinition(module.TypeSystem.String));il=stored.Body.GetILProcessor();text=il.Create(OpCodes.Ldstr,"Started");var read=il.Create(OpCodes.Ldloc_0);il.Append(text);il.Append(il.Create(OpCodes.Stloc_0));il.Append(il.Create(OpCodes.Br,read));il.Append(read);il.Append(il.Create(OpCodes.Call,label));il.Append(il.Create(OpCodes.Ret));Need(GuiCaptionAudit.Require(stored,text)==label.FullName,"Single display local and join succeed");
  var field=new FieldDefinition("model",FieldAttributes.Public|FieldAttributes.Static,module.TypeSystem.String);type.Fields.Add(field);var unsafeMethod=method();il=unsafeMethod.Body.GetILProcessor();text=il.Create(OpCodes.Ldstr,"Unit");il.Append(text);il.Append(il.Create(OpCodes.Dup));il.Append(il.Create(OpCodes.Stsfld,field));il.Append(il.Create(OpCodes.Call,label));il.Append(il.Create(OpCodes.Ret));bool rejected=false;try{GuiCaptionAudit.Require(unsafeMethod,text);}catch(Exception){rejected=true;}Need(rejected,"Model mutation rejected even with later GUI call");
  var escaped=method();il=escaped.Body.GetILProcessor();text=il.Create(OpCodes.Ldstr,"Unit");il.Append(text);il.Append(il.Create(OpCodes.Dup));il.Append(il.Create(OpCodes.Call,label));il.Append(il.Create(OpCodes.Stsfld,field));il.Append(il.Create(OpCodes.Ret));rejected=false;try{GuiCaptionAudit.Require(escaped,text);}catch(Exception){rejected=true;}Need(rejected,"A copy used after the GUI call cannot change the model");
  var style=new MethodReference("GetStyle",module.TypeSystem.Object,new TypeReference("UnityEngine","GUISkin",module,module.TypeSystem.CoreLibrary));style.Parameters.Add(new ParameterDefinition(module.TypeSystem.String));var styleMethod=method();il=styleMethod.Body.GetILProcessor();text=il.Create(OpCodes.Ldstr,"Button");il.Append(text);il.Append(il.Create(OpCodes.Call,style));il.Append(il.Create(OpCodes.Pop));il.Append(il.Create(OpCodes.Ret));rejected=false;try{GuiCaptionAudit.Require(styleMethod,text);}catch(Exception){rejected=true;}Need(rejected,"Style identifiers rejected");
  var format=new MethodReference("Format",module.TypeSystem.String,module.TypeSystem.String);format.Parameters.Add(new ParameterDefinition(module.TypeSystem.String));format.Parameters.Add(new ParameterDefinition(module.TypeSystem.Object));
  var formatted=method();il=formatted.Body.GetILProcessor();text=il.Create(OpCodes.Ldstr,"Price: {0}");il.Append(text);il.Append(il.Create(OpCodes.Ldnull));il.Append(il.Create(OpCodes.Call,format));il.Append(il.Create(OpCodes.Call,label));il.Append(il.Create(OpCodes.Ret));Need(GuiCaptionAudit.Require(formatted,text)==label.FullName,"Formatted numeric caption reaches display only");
  var formatModel=method();il=formatModel.Body.GetILProcessor();text=il.Create(OpCodes.Ldstr,"Unit {0}");il.Append(text);il.Append(il.Create(OpCodes.Ldnull));il.Append(il.Create(OpCodes.Call,format));il.Append(il.Create(OpCodes.Stsfld,field));il.Append(il.Create(OpCodes.Ret));rejected=false;try{GuiCaptionAudit.Require(formatModel,text);}catch(Exception){rejected=true;}Need(rejected,"Formatted model strings remain rejected");
  var input=new MethodReference("TextField",module.TypeSystem.String,gui);input.Parameters.Add(new ParameterDefinition(module.TypeSystem.String));input.Parameters.Add(new ParameterDefinition(new ArrayType(new TypeReference("UnityEngine","GUILayoutOption",module,module.TypeSystem.CoreLibrary))));
  var readOnly=method();il=readOnly.Body.GetILProcessor();text=il.Create(OpCodes.Ldstr,"Freeze");il.Append(text);il.Append(il.Create(OpCodes.Ldnull));il.Append(il.Create(OpCodes.Call,input));il.Append(il.Create(OpCodes.Pop));il.Append(il.Create(OpCodes.Ret));Need(GuiCaptionAudit.Require(readOnly,text)==input.FullName,"Discarded option field is display only");
  var writable=method();il=writable.Body.GetILProcessor();text=il.Create(OpCodes.Ldstr,"Set Name");il.Append(text);il.Append(il.Create(OpCodes.Ldnull));il.Append(il.Create(OpCodes.Call,input));il.Append(il.Create(OpCodes.Stsfld,field));il.Append(il.Create(OpCodes.Ret));rejected=false;try{GuiCaptionAudit.Require(writable,text);}catch(Exception){rejected=true;}Need(rejected,"Writable input must retain internal data");
  var joined=method();joined.Body.Variables.Add(new VariableDefinition(module.TypeSystem.String));il=joined.Body.GetILProcessor();text=il.Create(OpCodes.Ldstr,"Unknown");read=il.Create(OpCodes.Ldloc_0);var other=il.Create(OpCodes.Ldstr,"Default");il.Append(text);il.Append(il.Create(OpCodes.Stloc_0));il.Append(il.Create(OpCodes.Ldc_I4_0));il.Append(il.Create(OpCodes.Brfalse,other));il.Append(il.Create(OpCodes.Br,read));il.Append(other);il.Append(il.Create(OpCodes.Stloc_0));il.Append(read);il.Append(il.Create(OpCodes.Call,label));il.Append(il.Create(OpCodes.Ret));Need(GuiCaptionAudit.Require(joined,text)==label.FullName,"Branch-selected local has one display reader");
  var address=method();address.Body.Variables.Add(new VariableDefinition(module.TypeSystem.String));il=address.Body.GetILProcessor();text=il.Create(OpCodes.Ldstr,"Unknown");il.Append(text);il.Append(il.Create(OpCodes.Stloc_0));il.Append(il.Create(OpCodes.Ldloca,address.Body.Variables[0]));il.Append(il.Create(OpCodes.Pop));il.Append(il.Create(OpCodes.Ldloc_0));il.Append(il.Create(OpCodes.Call,label));il.Append(il.Create(OpCodes.Ret));rejected=false;try{GuiCaptionAudit.Require(address,text);}catch(Exception){rejected=true;}Need(rejected,"Local address escape rejected");
  var window=new MethodReference("MyWindow",module.TypeSystem.Void,new TypeReference("","GUIUtils",module,module.TypeSystem.CoreLibrary));foreach(string name in new[]{"Rect","GUI/WindowFunction","String","GUIStyle"})window.Parameters.Add(new ParameterDefinition(name=="String"?module.TypeSystem.String:new TypeReference("UnityEngine",name,module,module.TypeSystem.CoreLibrary)));var titleCaption=method();il=titleCaption.Body.GetILProcessor();il.Append(il.Create(OpCodes.Ldnull));il.Append(il.Create(OpCodes.Ldnull));text=il.Create(OpCodes.Ldstr,"Resize Map");il.Append(text);il.Append(il.Create(OpCodes.Ldnull));il.Append(il.Create(OpCodes.Call,window));il.Append(il.Create(OpCodes.Ret));Need(GuiCaptionAudit.Require(titleCaption,text)==window.FullName,"Fixed window title boundary accepted");
  Console.WriteLine("PASS GUI captions, discarded option fields and display joins; writable input, model writes and style identifiers rejected.");
 }
}
